package proute

import (
	"fmt"
	"io"
	"net/url"
	"strings"
	"unicode"

	"github.com/valyala/fasttemplate"
)

// Route is a request to be made
type Route struct {
	TemplatePath string  // the raw path with template locations. This should begin with a '/'
	PathCrumbs   []Crumb // Pieces of the path
	path         []byte  // cached rendered path
	query        []byte  // cached rendered query

	Method       string
	HeaderCrumbs []Crumb // can be static or various types
	headers      []KV

	QueryCrumbs []Crumb
	queryParams []KV

	BodyCrumbs  []Crumb
	body        []byte // rendered body
	ContentType []ContentType
}

func (r Route) QueryParams(generate bool) []KV {
	if generate || len(r.queryParams) == 0 {
		r.queryParams = r.queryParams[:0]
		for _, v := range r.QueryCrumbs {
			r.queryParams = append(r.queryParams, KV{Key: v.Key(), Value: v.Value()})
		}
	}
	return r.queryParams
}

type ContentType string

var (
	ContentTypeAny         ContentType = "any"
	ContentTypeJSON        ContentType = "application/json"
	ContentTypeFormData    ContentType = "multipart/form-data"
	ContentTypeXML         ContentType = "text/xml"
	ContentTypePlain       ContentType = "text/plain"
	ContentTypeFormEncoded ContentType = "application/x-www-form-urlencoded"
)

func DefaultValTagFunc(defaultv []byte, m map[string][]byte) func(w io.Writer, tag string) (int, error) {
	return func(w io.Writer, tag string) (int, error) {
		v, ok := m[tag]
		if !ok {
			return w.Write(defaultv)
		}
		if v == nil {
			return 0, nil
		}
		return w.Write(v)
	}
}

// Path returns a rendered path (with all the elements populated as a string)
// calling with generate=true will generate a new path using the crumbs provided. otherwise a cached
// version will be returned.
// we generate the path by substituting the values into the handlebars-esque template string provided
func (r Route) Path(generate bool) (string, error) {
	var err error
	if generate || len(r.path) == 0 {
		r.path = append(r.path[:0], r.TemplatePath...)
		t, err := fasttemplate.NewTemplate(r.TemplatePath, "{", "}")
		if err != nil {
			return r.TemplatePath, fmt.Errorf("failed to compile template: %w", err)
		}

		// generate our template string. by default we use 42 as a default value as its both a string and a numeric
		vals := make(map[string][]byte)
		for _, v := range r.PathCrumbs {
			vals[v.Key()] = []byte(v.Value())
		}
		r.path = append(r.path[:0], t.ExecuteFuncString(DefaultValTagFunc([]byte("42"), vals))...)

		if strings.ContainsAny(string(r.path), "{}") {
			err = fmt.Errorf("path still contains template tokens")
			// log.Trace().Str("base", r.TemplatePath).Str("result", string(r.path)).Msg("rendered path still contains template tokens")
		}
	}
	return string(r.path), err
}

// Query will generate the full query string not including the ? e.g. foo=bar&baz=boo
// Query Parameters will be pulled from the route QueryCrumbs
// We can add extra query params. These will be written first, and the route query params will override the provided
func (r Route) Query(generate bool, extraParams ...KV) (string, error) {
	if generate || len(r.query) == 0 {

		// only generate if there are params to generate
		if len(extraParams) == 0 && len(r.QueryParams(generate)) == 0 {
			return "", nil
		}

		params := make([]KV, 0)
		params = append(params, extraParams...)
		params = append(params, r.QueryParams(generate)...)

		qp := make(url.Values)
		for _, v := range params {
			qp.Add(v.Key, v.Value)
		}
		r.query = append(r.query, qp.Encode()...)
	}
	return string(r.query), nil
}

// Path returns a rendered body (with all the elements populated as a string)
// calling with generate=true will generate a new path using the crumbs provided. otherwise a cached
// version will be returned
// ContentType can be a specified contentType, or ContentTypeAny. If Any, this will attempt to deduce
// the content type based on the route data
func (r Route) Body(generate bool, contentType ContentType) []byte {
	if generate || len(r.body) == 0 {
		r.body = r.body[:0]
		// need to handle the case of 1 xml BodyCrumb thats the entire object
		// we don't want to wrap the object with pointless tags
		if len(r.BodyCrumbs) == 1 && contentType == ContentTypeXML {
			r.body = []byte(MarshalXMLCrumb(r.BodyCrumbs[0], CrumbOptContentType(contentType)))
		} else if strings.Contains(string(contentType), "multipart/form-data") {
			r.body = []byte(ObjectCrumb{Name: "root", Elements: r.BodyCrumbs}.Value(CrumbOptContentType(ContentTypeFormData)))
		} else {
			r.body = []byte(ObjectCrumb{Name: "root", Elements: r.BodyCrumbs}.Value(CrumbOptContentType(contentType)))
		}
	}
	return r.body
}

func (r Route) Headers(generate bool) []KV {
	if generate || len(r.headers) == 0 {
		r.headers = r.headers[:0]
		for _, v := range r.HeaderCrumbs {
			// strip not spaces because that makes it an invalid header
			k := stripNonSpaceWhitespace(v.Key())
			val := stripNonSpaceWhitespace(v.Value())
			r.headers = append(r.headers, KV{Key: k, Value: val})
		}
	}
	return r.headers
}

func stripNonSpaceWhitespace(v string) string {
	buf := make([]byte, 0, len(v))
	for _, c := range v {
		if unicode.IsSpace(c) && c != ' ' {
			continue
		}
		buf = append(buf, string(c)...)
	}
	return string(buf)
}

type KV struct {
	Key   string
	Value string
}
// proute or Paramaterised-Routes allow for customisable paths with arbitrary parameters that can be generated
// to produce a full request. This is our intermediate representation between kitebuilder and kiterunner.
// This also can further be extended for programmatic use allowing for fuzzable parameters
package proute

import (
	"fmt"

	"github.com/segmentio/ksuid"
)

// API encapsulates all the routes and required headers for the routes
type API struct {
	URL    string  // the URL source of the API
	ID     string  // the Ksuid for this API which can be any UUID really... but KSUID is convenient
	Routes []Route // a list of routes

	// Crumbs to add to all the Routes
	QueryCrumbs []Crumb
	queryParams []KV

	HeaderCrumbs []Crumb
	headers      []KV

	BodyCrumbs []Crumb
	bodyParams []KV

	CookieCrumbs []Crumb
	cookieParams []KV
}

// APIS are multiple APIs, defined as a type for convenience
type APIS []API

func FromAPISlice(a []API) APIS {
	return append(APIS{}, a...)
}

func (a APIS) First(n int) APIS {
	if n == 0 {
		return a
	}

	ret := make(APIS, 0)
	count := 0
	for _, v := range a {
		if count+len(v.Routes) <= n {
			count += len(v.Routes)
			ret = append(ret, v)
		} else {
			// count + len(v.Routes) > n
			// we're over the limit so truncate
			remainder := n - count
			v.Routes = v.Routes[:remainder]

			count += remainder
			ret = append(ret, v)
			return ret
		}
	}
	return ret
}

func (a API) DebugPrint() {
	url := a.URL
	if url == "" {
		url = "<no-url>"
	}

	fmt.Printf("%s {%s}\n", url, a.ID)
	if len(a.HeaderCrumbs) > 0 {
		fmt.Printf("\theaders: %s\n", crumbString(a.HeaderCrumbs))
	}
	if len(a.QueryCrumbs) > 0 {
		fmt.Printf("\tquery: %s\n", crumbString(a.QueryCrumbs))
	}
	if len(a.CookieCrumbs) > 0 {
		fmt.Printf("\tcookie: %s\n", crumbString(a.CookieCrumbs))
	}
	if len(a.BodyCrumbs) > 0 {
		fmt.Printf("\tbody: %s\n", crumbString(a.BodyCrumbs))
	}

	for _, route := range a.Routes {
		p, _ := route.Path(false)
		fmt.Printf("\t%s %s Query(%s) Header(%s)\n", route.Method, p, crumbString(route.QueryCrumbs), crumbString(route.HeaderCrumbs))
	}
}

func (a API) QueryParams(generate bool) []KV {
	if generate || len(a.queryParams) == 0 {
		a.queryParams = a.queryParams[:0]
		for _, v := range a.QueryCrumbs {
			a.queryParams = append(a.queryParams, KV{Key: v.Key(), Value: v.Value()})
		}
	}
	return a.queryParams
}

func (a API) CookieParams(generate bool) []KV {
	if generate || len(a.cookieParams) == 0 {
		a.cookieParams = a.cookieParams[:0]
		for _, v := range a.CookieCrumbs {
			a.cookieParams = append(a.cookieParams, KV{Key: v.Key(), Value: v.Value()})
		}
	}
	return a.cookieParams
}

func (a API) BodyParams(generate bool) []KV {
	if generate || len(a.bodyParams) == 0 {
		a.bodyParams = a.bodyParams[:0]
		for _, v := range a.BodyCrumbs {
			a.bodyParams = append(a.bodyParams, KV{Key: v.Key(), Value: v.Value()})
		}
	}
	return a.bodyParams
}

func (a API) Headers(generate bool) []KV {
	if generate || len(a.headers) == 0 {
		a.headers = a.headers[:0]
		for _, v := range a.HeaderCrumbs {
			a.headers = append(a.headers, KV{Key: v.Key(), Value: v.Value()})
		}
	}
	return a.headers
}

func NewAPI(id string, url string) API {
	if id == "" {
		id = ksuid.New().String()
	}
	return API{
		ID:  id,
		URL: url,
	}
}
package proute

import (
	"bufio"
	"io"
	"strings"

	"github.com/hashicorp/go-multierror"
	"github.com/segmentio/ksuid"
)

type PRouteOptions struct {
	HeaderCrumbs []Crumb
	QueryCrumbs  []Crumb
	PathCrumbs   []Crumb
	BodyCrumbs   []Crumb
	Method       string
	ID string
	ContentType  []ContentType
}
type PRouteOption func(o *PRouteOptions)

func OptHeader(c Crumb) PRouteOption {
	return func(o *PRouteOptions) {
		o.HeaderCrumbs = append(o.HeaderCrumbs, c)
	}
}
func OptQuery(c Crumb) PRouteOption {
	return func(o *PRouteOptions) {
		o.QueryCrumbs = append(o.QueryCrumbs, c)
	}
}
func OptPath(c Crumb) PRouteOption {
	return func(o *PRouteOptions) {
		o.PathCrumbs = append(o.PathCrumbs, c)
	}
}
func OptBody(c Crumb) PRouteOption {
	return func(o *PRouteOptions) {
		o.BodyCrumbs = append(o.BodyCrumbs, c)
	}
}
func OptID(ID string) PRouteOption {
	return func(o *PRouteOptions) {
		o.ID = ID
	}
}
func OptMethod(method string) PRouteOption {
	return func(o *PRouteOptions) {
		o.Method = method
	}
}
func OptContentType(v string) PRouteOption {
	return func(o *PRouteOptions) {
		o.ContentType = append(o.ContentType, ContentType(v))
	}
}

func FromStringSliceReader(r io.Reader, source string, opts...PRouteOption) (API, error) {
	scanner := bufio.NewScanner(r)

	lines := make([]string, 0)
	for scanner.Scan() {
		lines = append(lines, strings.Trim(scanner.Text(), " "))
	}
	return FromStringSlice(lines, source, opts...)
}

// FromStringSlice will convert a string slice of paths into a Proute API. You can provide options to configure
// all the proutes at the same time, but not any individually
func FromStringSlice(in []string, source string, opts ...PRouteOption) (API, error) {
	ret := API{
		URL: source,
	}

	o := &PRouteOptions{
		Method: "GET",
		ID: ksuid.New().String(),
	}

	for _, v := range opts {
		v(o)
	}
	ret.ID = o.ID

	for _, v := range in {
		if len(v) == 0 {
			continue
		}
		if v[0] != '/' {
			v = "/" + v
		}

		route := Route{
			TemplatePath: v,
			Method:       o.Method,
			ContentType:  o.ContentType,
			HeaderCrumbs: o.HeaderCrumbs,
			PathCrumbs:   o.PathCrumbs,
			BodyCrumbs:   o.BodyCrumbs,
			QueryCrumbs:  o.QueryCrumbs,
		}
		ret.Routes = append(ret.Routes, route)
	}
	return ret, nil
}

func (a APIS) EncodeStringSlice(w io.Writer) (error) {
	var merr *multierror.Error
	for _, api := range a {
		for _, route := range api.Routes {
			path, err:= route.Path(true)
			if err != nil {
				multierror.Append(merr, err)
				continue
			}
			w.Write([]byte(path + "\n"))
		}
	}
	return merr.ErrorOrNil()
}

package kitebuilder

import (

	// "github.com/goccy/go-json"
	"encoding/json"
	"fmt"
	"io"
	"io/ioutil"
	"os"
	"reflect"

	errors2 "github.com/assetnote/kiterunner/pkg/errors"
	"github.com/assetnote/kiterunner/pkg/log"
	"github.com/hashicorp/go-multierror"
)

// LoadJSONFile will load the json schema from the specified file
func LoadJSONFile(filename string) (schema []API, err error) {
	jsonFile, err := os.Open(filename)
	if err != nil {
		return
	}
	defer jsonFile.Close()

	data, err := ioutil.ReadAll(jsonFile)
	if err != nil {
		return
	}

	return LoadJSONBytes(data)
}

func LoadJSONReader(r io.Reader) (schema []API, err error) {
	res, err := ioutil.ReadAll(r)
	if err != nil {
		return nil, err
	}
	return LoadJSONBytes(res)
}

// SlowLoadJSONFile will load the json schema from the specified file
func SlowLoadJSONFile(filename string) (schema []API, err error) {
	jsonFile, err := os.Open(filename)
	if err != nil {
		return
	}
	defer jsonFile.Close()

	data, err := ioutil.ReadAll(jsonFile)
	if err != nil {
		return
	}

	return SlowLoadJSONBytes(data)
}

// LoadJSONBytes will load the schema from the provided bytes
func LoadJSONBytes(buf []byte) ([]API, error) {
	var ret []API
	if err := json.Unmarshal(buf, &ret); err != nil {
		return ret, fmt.Errorf("failed to unmarshal json: %w", err)
	}
	return ret, nil
}

// SlowLoadJSONBytes will unmarshal the buf into an interface{} and attempt
// to unmarshal each individual API while printing errors about the object
// This is a painful manual process when the kitebuilder spec was non-finalised
func SlowLoadJSONBytes(buf []byte) ([]API, error) {
	var (
		ret    []API
		all    []interface{}
		merr = &multierror.Error{}
	)
	log.Debug().Msg("beginning slow load of json bytes")
	if err := json.Unmarshal(buf, &all); err != nil {
		return ret, fmt.Errorf("failed to unmarshal json: %w", err)
	}

	for _, v := range all {
		// encode json for debugging
		bv, err := json.Marshal(v)
		if err != nil {
			return ret, fmt.Errorf("failed to encode object: %w", err)
		}

		switch v.(type) {
		case []interface{}:
			// this is a nested slice
			for _, v := range v.([]interface{}) {
				// encode json for debugging
				bv, err := json.Marshal(v)
				if err != nil {
					log.Trace().Err(err).Msg("failed to encode object")
				}

				switch v.(type) {
				case map[string]interface{}:
					// we have reached the API object
					a, err := unmarshalToAPI(v.(map[string]interface{}))
					if err != nil {
						merr = multierror.Append(merr, &errors2.ParserError{
							ID:      "root",
							RawJSON: bv,
							Err:     fmt.Errorf("failed to unmarhsal api: %w", err),
							Context: "root.[].[].v",
						})
					}
					ret = append(ret, a)
				default:
					got := reflect.TypeOf(v).Kind()
					merr = multierror.Append(merr, &errors2.ParserError{
						ID:      "root",
						RawJSON: bv,
						Err:     fmt.Errorf("unexpected type: %s", got),
						Context: "root.[].[].v",
					})
				}
			}
		case map[string]interface{}:
			// we have reached the API object
			a, err := unmarshalToAPI(v.(map[string]interface{}))
			if err != nil {
				merr = multierror.Append(merr, &errors2.ParserError{
					ID:      "root",
					RawJSON: bv,
					Err:     fmt.Errorf("failed to unmarshal api: %w", err),
					Context: "root.[].v",
				})
			}
			ret = append(ret, a)
		default:
			got := reflect.TypeOf(v).Kind()
			merr = multierror.Append(merr, &errors2.ParserError{
				ID:      "root",
				RawJSON: bv,
				Err:     fmt.Errorf("unexpected type: %s", got),
				Context: "root.[].v",
			})
		}
	}
	return ret, merr.ErrorOrNil()
}

func unmarshalToAPI(v map[string]interface{}) (API, error) {
	var (
		ret  API
		err  error
		merr = &multierror.Error{}
	)

	ret.SecurityDefinitions = make(map[string]SecurityDefinition)
	ret.Paths = make(map[Path]Operations)

	bv, err := json.Marshal(v)
	if err != nil {
		return ret, fmt.Errorf("failed to marshal map for input: %w", err)
	}

	// decode url
	ret.URL, err = GetMapString(v, "url")
	if err != nil {
		merr = multierror.Append(merr, &errors2.ParserError{
			Context: "api",
			Err:     fmt.Errorf("failed to get url: %w", err),
			RawJSON: bv,
		})
	}

	// decode id
	ret.ID, err = GetMapString(v, "ksuid")
	if err != nil {
		merr = multierror.Append(merr, &errors2.ParserError{
			Context: "api",
			Err:     fmt.Errorf("failed to get api id: %w", err),
			RawJSON: bv,
		})
	}

	log.Trace().Str("url", ret.URL).Str("id", ret.ID).Msg("parsing api")
	if err := UnmarshalJSONString(v, "securityDefinitions", &ret.SecurityDefinitions); err != nil {
		merr = multierror.Append(merr, &errors2.ParserError{
			ID:      ret.ID,
			Context: "api",
			Err:     fmt.Errorf("failed to get security definitions: %w", err),
			RawJSON: bv,
		})
	}

	// decode paths
	if v, ok := v["paths"]; ok {
		if mv, ok := v.(map[string]interface{}); ok {
			for path, v := range mv {
				ret.Paths[Path(path)] = make(map[OperationTypes]Operation)
				if opv, ok := v.(map[string]interface{}); ok {
					for operation, v := range opv {
						bv, err := json.Marshal(v)
						if err != nil {
							return ret, fmt.Errorf("failed to marshal map for input: %w", err)
						}

						if op, ok := v.(map[string]interface{}); ok {
							var o Operation
							if o.Description, err = GetMapString(op, "description"); err != nil {
								merr = multierror.Append(merr, &errors2.ParserError{
									ID:      ret.ID,
									Route:   path,
									Method:  operation,
									Context: "api.paths.operations.v",
									Err:     fmt.Errorf("failed to get operation description: %w", err),
									RawJSON: bv,
								})
							}
							if o.OperationID, err = GetMapString(op, "operationId"); err != nil {
								merr = multierror.Append(merr, &errors2.ParserError{
									ID:      ret.ID,
									Route:   path,
									Method:  operation,
									Context: "api.paths.operations.v",
									Err:     fmt.Errorf("failed to get operation id: %w", err),
									RawJSON: bv,
								})
							}

							if err := UnmarshalJSONString(op, "consumes", &o.Consumes); err != nil {
								merr = multierror.Append(merr, &errors2.ParserError{
									ID:      ret.ID,
									Route:   path,
									Method:  operation,
									Context: "api.paths.operations.v",
									Err:     fmt.Errorf("failed to get consumes: %w", err),
									RawJSON: bv,
								})
							}

							if err := UnmarshalJSONString(op, "produces", &o.Produces); err != nil {
								merr = multierror.Append(merr, &errors2.ParserError{
									ID:      ret.ID,
									Route:   path,
									Method:  operation,
									Context: "api.paths.operations.v",
									Err:     fmt.Errorf("failed to get produces: %w", err),
									RawJSON: bv,
								})
							}

							if v, ok := op["parameters"]; ok {
								if err := unmarshalToParameters(v, &o.Parameters); err != nil {
									merr = multierror.Append(merr, &errors2.ParserError{
										ID:      ret.ID,
										Route:   path,
										Method:  operation,
										Context: "api.paths.operations.parameters",
										Err:     fmt.Errorf("failed to get parameters: %w", err),
										RawJSON: bv,
									})
								}
							}

							ret.Paths[Path(path)][OperationTypes(operation)] = o
						} else {
							got := reflect.TypeOf(v).Kind()
							merr = multierror.Append(merr, &errors2.ParserError{
								ID:      ret.ID,
								Route:   path,
								Method:  operation,
								Context: "api.paths.operations.v",
								Err:     fmt.Errorf("unexpected type for operation: %s", got),
								RawJSON: bv,
							})
						}
					}
				} else {
					got := reflect.TypeOf(v).Kind()
					merr = multierror.Append(merr, &errors2.ParserError{
						ID:      ret.ID,
						Route:   path,
						Context: "api.paths.operations",
						Err:     fmt.Errorf("unexpected type for operations map: %s", got),
						RawJSON: bv,
					})
				}
			}
		} else {
			got := reflect.TypeOf(v).Kind()
			merr = multierror.Append(merr, &errors2.ParserError{
				ID:      ret.ID,
				Context: "api.paths",
				Err:     fmt.Errorf("unexpected type for path: %s", got),
				RawJSON: bv,
			})
		}
	} else {
		merr = multierror.Append(merr, &errors2.ParserError{
			ID:      ret.ID,
			Context: "api",
			Err:     fmt.Errorf("missing paths"),
			RawJSON: bv,
		})
	}

	return ret, merr.ErrorOrNil()
}

func unmarshalToParameters(params interface{}, dst *[]Parameter) error {
	merr := &multierror.Error{}

	rootbv, err := json.Marshal(params)
	if err != nil {
		log.Trace().Err(err).Msg("failed to encode object")
	}

	switch params.(type) {
	case []interface{}:
		for _, params := range params.([]interface{}) {
			switch params.(type) {
			case []interface{}:
				// nested slices
				for _, v := range params.([]interface{}) {
					// if we hit a nil we should just skippo
					if v == nil {
						merr = multierror.Append(merr, &errors2.ParserError{
							RawJSON: rootbv,
							Context: "param.[].[].v",
							Err:     fmt.Errorf("found unexpected nil"),
						})
					}

					bv, err := json.Marshal(v)
					if err != nil {
						merr = multierror.Append(merr, &errors2.ParserError{
							RawJSON: rootbv,
							Context: "param.[].[].v",
							Err:     fmt.Errorf("failed to marshal object: %w", err),
						})
					}

					var tmp Parameter
					if vv, ok := v.(map[string]interface{}); ok {
						err = json.Unmarshal(bv, &tmp)
						if err != nil {
							merr = multierror.Append(merr, &errors2.ParserError{
								RawJSON: bv,
								Context: "param.[].[].map[string]interface{}",
