func APIsToKiterunnerRoutes(api []API) ([]*http.Route, error) {
	var merr *multierror.Error
	ret := make([]*http.Route, 0)
	for _, v := range api {
		tmp, err := ToKiterunnerRoutes(v)
		if err != nil {
			multierror.Append(merr, err)
		}
		ret = append(ret, tmp...)
	}
	return ret, merr.ErrorOrNil()
}

func ToKiterunnerRoutes(api API) ([]*http.Route, error) {
	var merr *multierror.Error

	ret := make([]*http.Route, 0)
	for _, v := range api.Routes {
		// Skip these options since we don't actually care about the content here
		r, err := v.ToKiterunner(api.Headers(true)...)
		if err != nil {
			multierror.Append(merr, err)
		}
		switch string(r.Method) {
		case "HEAD", "OPTIONS", "CONNECT", "TRACE":
			// we're biased. skip these since they're noisy
			continue
		case "GET", "POST", "PUT", "DELETE", "PATCH":
			// these guys are alright
		}

		r.Source = api.ID
		ret = append(ret, r)
	}
	return ret, merr.ErrorOrNil()
}

func (r Route) ToKiterunner(extraHeaders ...KV) (*http.Route, error) {
	var err error

	method := strings.TrimSpace(strings.ToUpper(r.Method))
	switch method {
	case "HEAD", "OPTIONS", "CONNECT", "TRACE":
		// we're biased. skip these since they're noisy
	case "GET", "POST", "PUT", "DELETE", "PATCH":
		// these guys are alright
	default:
		method = "GET"
	}

	ret := &http.Route{
		Path:   []byte(r.path),
		Method: http.Method(method),
	}
	for _, h := range r.Headers(true) {
		ret.Headers = append(ret.Headers, http.Header{h.Key, h.Value})
	}

	for _, h := range extraHeaders {
		ret.Headers = append(ret.Headers, http.Header{h.Key, h.Value})
	}

	ct := ContentTypeFormEncoded
	if len(r.ContentType) > 0 {
		ct = r.ContentType[0]
		// Overwrite the form-data format with a proper boundary header
		if strings.Contains(string(ct), "form-data") {
			ct = "multipart/form-data; boundary=" + DefaultFormDataBoundary
		}
	}
	ret.Body = r.Body(true, ct)

	// only add content type if there is a body specified
	// or if its a non-get type
	if len(ret.Body) > 0 || (string(ret.Method) != string(http.GET)) {
		ret.Headers = append(ret.Headers, http.Header{"Content-Type", string(ct)})
	}

	tmp, err := r.Path(false)
	if err != nil {
		return ret, err
	}
	ret.Path = []byte( tmp )

	tmp, err = r.Query(false)
	ret.Query = []byte(tmp)
	return ret, err
}

package http

import (
	"fmt"
	"strings"
	"sync"

	"github.com/rs/zerolog"
)

type Method []byte

var (
	GET    Method = []byte("GET")
	POST   Method = []byte("POST")
	PATCH  Method = []byte("PATCH")
	DELETE Method = []byte("DELETE")
	PUT    Method = []byte("PUT")
	TRACE  Method = []byte("TRACE")

	ErrUnsupportedMethod = fmt.Errorf("unsupported method")
)

func MethodFromString(m string) (Method, error) {
	switch strings.ToUpper(m) {
	case "GET":
		return GET, nil
	case "POST":
		return POST, nil
	case "PATCH":
		return PATCH, nil
	case "DELETE":
		return DELETE, nil
	case "PUT":
		return PUT, nil
	case "TRACE":
		return TRACE, nil
	}
	return GET, ErrUnsupportedMethod
}

var (
	bSlash = []byte("/")
)

type ChunkedRoutes [][]*Route

var (
	ChunkedRoutesPool sync.Pool
)

// acquireChunkedRoutes retrieves a host from the shared header pool
func AcquireChunkedRoutes() *ChunkedRoutes {
	v := ChunkedRoutesPool.Get()
	if v == nil {
		v := make(ChunkedRoutes, 0)
		return &v
	}
	return v.(*ChunkedRoutes)
}

// releaseChunkedRoutes releases a host into the shared header pool
func ReleaseChunkedRoutes(h *ChunkedRoutes) {
	*h = (*h)[:0]
	ChunkedRoutesPool.Put(h)
}

func ChunkRoutes(items []*Route, src *ChunkedRoutes, chunks int) *ChunkedRoutes {
	chunkSize := (len(items) / chunks) + 1
	for chunkSize < len(items) {
		items, *src = items[chunkSize:], append(*src, items[0:chunkSize:chunkSize])
	}

	*src = append(*src, items)
	return src
}

type Route struct {
	Headers []Header
	Path    []byte
	Query   []byte
	Source  string
	Method  Method
	Body    []byte
}

func (r Route) String() string {
	return fmt.Sprintf("%s %s%s", r.Method, r.Path, r.Query)
}

func (r Route) MarshalZerologObject(e *zerolog.Event) {
	e.Bytes("method", r.Method).
		Bytes("path", r.Path).
		Bytes("query", r.Query).
		Array("headers", Headers(r.Headers))
}

func (r Route) AppendShortBytes(b []byte) []byte {
	b = append(b, r.Method...)
	b = append(b, " "...)
	b = append(b, r.Path...)
	return b
}

func (r Route) AppendBytes(b []byte) []byte {
	b = append(b, r.Method...)
	b = append(b, " "...)
	b = r.AppendPath(b)
	if len(r.Query) > 0 {
		b = append(b, "?"...)
		b = r.AppendQuery(b)
	}
	b = append(b, " HTTP/1.1\r\n"...)

	for _, v := range r.Headers {
		b = v.AppendBytes(b)
		b = append(b, "\r\n"...)
	}

	b = append(b, "\r\n"...)
	b = append(b, r.Body...)
	return b
}

func (r *Route) AppendPath(dst []byte) []byte {
	dst = append(dst, r.Path...)
	return dst

}

func (r *Route) AppendQuery(dst []byte) []byte {
	dst = append(dst, r.Query...)
	return dst
}
package http

// getDepth will return up to the N'th+1 slash in the path.
// e.g. /foo/bar/baz depth 2 will return /foo/bar
// If a prefix slash is not included, we will prepend the prefix slash,
// e.g. foo/bar/baz depth 2 will return /foo/bar
// If there is insufficient path elements, we will return the input element
func getDepth(path string, depth int64) (ret string) {
	// if we wanted no depth, then the basepath is empty
	if depth == 0 {
		return ""
	}

	// not sure how this is possible but sure
	if len(path) == 0 {
		return path
	}

	if path[0] != '/' {
		path = "/" + path
	}
	var hits int64 = 0
	for i, v := range path {
		if v == '/' {
			hits++
		}

		if hits == depth+1 {
			return path[0:i]
			break
		}
	}

	return path
}

type RouteMap map[string][]*Route

func (r RouteMap) FlattenCount() int {
	ret := 0
	for _, v := range r {
		ret += len(v)
	}
	return ret
}

func (r RouteMap) Flatten() []*Route {
	ret := make([]*Route, 0)
	for _, v := range r {
		ret = append(ret, v...)
	}
	return ret
}

// GroupRouteDepth will collate the routes into the corresponding depth of path
func GroupRouteDepth(routes []*Route, depth int64) RouteMap {
	ret := make(map[string][]*Route)
	for _, v := range routes {
		basePath := getDepth(string(v.Path), depth)
		ret[basePath] = append(ret[basePath], v)
	}
	return ret
}

// UniqueSource will unique the routes based on the ID
func UniqueSource(routes []*Route) []*Route {
	ret := make([]*Route, 0)
	seen := make(map[string]interface{})
	for _, v := range routes {
		if _, ok := seen[v.Source]; ok {
			continue
		}
		seen[v.Source] = struct{}{}
		ret = append(ret, v)
	}
	return ret
}

// FilterSource will only return the routes that exist in the map provided
func FilterSource(routes []*Route, want map[string]interface{}) []*Route {
	ret := make([]*Route, 0)
	for _, v := range routes {
		if _, ok := want[v.Source]; !ok {
			continue
		}
		ret = append(ret, v)
	}
	return ret
}

