func TestDebugBookSchema(t *testing.T) {
	data, _ := ioutil.ReadFile("testdata/bookstore-v3.json")
	root, _ := decodeDocument(data)
	components, _ := asMap(root["components"])
	schemas, _ := asMap(components["schemas"])
	s := schemaFromValue(root, schemas["BookInput"], make(map[string]bool))
	b, _ := json.MarshalIndent(s, "", "  ")
	t.Log(string(b))

	api, _, _, _, _, _ := buildAPI(root, "debug")
	_, perr := proute.FromKitebuilderAPI(*api)
	var merr *multierror.Error
	if errors.As(perr, &merr) {
		for _, e := range merr.Errors {
			var pe *kerrors.ParserError
			if errors.As(e, &pe) {
				logParserError(t, pe, 0)
			}
		}
	}
}

func logParserError(t *testing.T, pe *kerrors.ParserError, depth int) {
	t.Helper()
	t.Logf("%*s%s: %v", depth*2, "", pe.Context, pe.Err)
	var merr *multierror.Error
	if errors.As(pe.Err, &merr) {
		for _, e := range merr.Errors {
			var child *kerrors.ParserError
			if errors.As(e, &child) {
				logParserError(t, child, depth+1)
			} else {
				t.Logf("%*s%v", (depth+1)*2, "", e)
			}
		}
	}
}

