// Package openapi provides OpenAPI/Swagger driven route generation for
// kiterunner. Documents are parsed into the same proute representation used by
// kitebuilder wordlists, so quick scans, full scans, filters and all existing
// scan options keep working unchanged.
package openapi

import (
	"bytes"
	"crypto/sha1"
	"encoding/hex"
	"fmt"
	"io"
	"io/ioutil"
	"sort"
	"strings"

	"github.com/assetnote/kiterunner/pkg/kitebuilder"
	"github.com/assetnote/kiterunner/pkg/proute"
)

// Document is a parsed OpenAPI/Swagger document.
type Document struct {
	Source     string
	Version    string
	Title      string
	BasePath   string
	ServerURL  string
	Operations []Operation
	Warnings   []string

	// API is the generated intermediate route document.
	API proute.API
}

// LoadFile parses an OpenAPI or Swagger document from disk.
func LoadFile(filename string) (*Document, error) {
	data, err := ioutil.ReadFile(filename)
	if err != nil {
		return nil, fmt.Errorf("failed to read openapi file: %w", err)
	}
	return LoadBytes(data, filename)
}

// ParseFile is an alias for LoadFile.
func ParseFile(filename string) (*Document, error) {
	return LoadFile(filename)
}

// LoadReader parses an OpenAPI or Swagger document from a reader.
func LoadReader(r io.Reader, source string) (*Document, error) {
	data, err := ioutil.ReadAll(r)
	if err != nil {
		return nil, fmt.Errorf("failed to read openapi document: %w", err)
	}
	return LoadBytes(data, source)
}

// ParseReader is an alias for LoadReader.
func ParseReader(r io.Reader, source string) (*Document, error) {
	return LoadReader(r, source)
}

// LoadBytes parses JSON or YAML OpenAPI/Swagger bytes.
func LoadBytes(data []byte, source string) (*Document, error) {
	root, err := decodeDocument(data)
	if err != nil {
		return nil, err
	}

	version := asString(root["openapi"])
	if version == "" {
		version = asString(root["swagger"])
	}
	if version == "" {
		return nil, fmt.Errorf("not an OpenAPI or Swagger document: missing openapi/swagger version")
	}

	api, operations, basePath, serverURL, warnings, err := buildAPI(root, source)
	if err != nil {
		return nil, err
	}

	proutes, err := proute.FromKitebuilderAPI(*api)
	if err != nil {
		warnings = append(warnings, err.Error())
	}

	title := ""
	if info, ok := asMap(root["info"]); ok {
		title = asString(info["title"])
	}

	return &Document{
		Source:     source,
		Version:    version,
		Title:      title,
		BasePath:   basePath,
		ServerURL:  serverURL,
		Operations: operations,
		Warnings:   warnings,
		API:        proutes,
	}, nil
}

// Parse parses OpenAPI/Swagger bytes. The source is set to "<input>".
func Parse(data []byte) (*Document, error) {
	return LoadBytes(data, "<input>")
}

// LoadOpenAPIFile is an explicit alias for LoadFile.
func LoadOpenAPIFile(filename string) (*Document, error) {
	return LoadFile(filename)
}

// LoadOpenAPIBytes is an explicit alias for LoadBytes.
func LoadOpenAPIBytes(data []byte, source string) (*Document, error) {
	return LoadBytes(data, source)
}

// IsOpenAPI reports whether data decodes to an OpenAPI or Swagger document.
func IsOpenAPI(data []byte) bool {
	if !bytes.Contains(data, []byte("openapi")) && !bytes.Contains(data, []byte("swagger")) {
		return false
	}
	root, err := decodeDocument(data)
	if err != nil {
		return false
	}
	return asString(root["openapi"]) != "" || asString(root["swagger"]) != ""
}

// ToKitebuilder returns the intermediate representation for callers that want
// to compile the generated routes into a .kite wordlist.
func (d *Document) ToKitebuilder() (kitebuilder.API, error) {
	return d.API.ToKitebuilderAPI()
}

// OperationKeys returns sorted, canonical METHOD /path keys for the source
// spec operations.
func (d *Document) OperationKeys() []string {
	ret := make([]string, 0, len(d.Operations))
	for _, operation := range d.Operations {
		ret = append(ret, operation.Key())
	}
	return sortUnique(ret)
}

// GeneratedRouteKeys returns sorted, canonical METHOD /path keys for every
// route generated from the spec.
func (d *Document) GeneratedRouteKeys() []string {
	ret := make([]string, 0, len(d.API.Routes))
	for _, route := range d.API.Routes {
		ret = append(ret, RouteKey(route.Method, route.TemplatePath))
	}
	return sortUnique(ret)
}

// ScannableRouteKeys returns the generated routes that survive conversion to
// the request model used by the kiterunner engine. HEAD, OPTIONS and TRACE are
// intentionally not scanned by kiterunner today.
func (d *Document) ScannableRouteKeys() []string {
	ret := make([]string, 0, len(d.API.Routes))
	for _, route := range d.API.Routes {
		method := strings.ToUpper(route.Method)
		if !scannableMethod(method) {
			continue
		}
		if _, err := route.ToKiterunner(d.API.Headers(true)...); err != nil {
			continue
		}
		ret = append(ret, RouteKey(method, route.TemplatePath))
	}
	return sortUnique(ret)
}

// CoverageReport compares spec operations to generated routes and reports the
// routes that would actually be scanned.
func (d *Document) CoverageReport() CoverageReport {
	spec := d.OperationKeys()
	generated := d.GeneratedRouteKeys()
	scannable := d.ScannableRouteKeys()
	specCoverage := compareCoverage(spec, generated)

	return CoverageReport{
		Source:          d.Source,
		Title:           d.Title,
		Version:         d.Version,
		BasePath:        d.BasePath,
		ServerURL:       d.ServerURL,
		Spec:            specCoverage,
		CoveragePercent: specCoverage.Percent,
		Scannable:       compareCoverage(spec, scannable),
		Warnings:        append([]string{}, d.Warnings...),
	}
}

// CoverageReportWithManual compares generated routes against a manually
// curated list of METHOD /path entries.
func (d *Document) CoverageReportWithManual(manual []string) CoverageReport {
	ret := d.CoverageReport()
	coverage := compareCoverage(manual, d.GeneratedRouteKeys())
	ret.Manual = &coverage
	ret.ManualCoveragePercent = coverage.Percent
	return ret
}

func scannableMethod(method string) bool {
	switch method {
	case "GET", "POST", "PUT", "PATCH", "DELETE":
		return true
	default:
		return false
	}
}

func stableID(parts ...string) string {
	h := sha1.New()
	for _, part := range parts {
		_, _ = h.Write([]byte(part))
		_, _ = h.Write([]byte{0})
	}
	return hex.EncodeToString(h.Sum(nil))
}

func sortUnique(values []string) []string {
	seen := make(map[string]bool, len(values))
	ret := make([]string, 0, len(values))
	for _, value := range values {
		if seen[value] {
			continue
		}
		seen[value] = true
		ret = append(ret, value)
	}
	sort.Strings(ret)
	return ret
}
package openapi

import (
	"fmt"
	"net/url"
	"sort"
	"strings"

	"github.com/assetnote/kiterunner/pkg/kitebuilder"
)

// Operation is an OpenAPI path + method pair. It is kept separately from the
// generated proute so coverage can be calculated even if a generator warning
// caused a route to be skipped.
type Operation struct {
	Method      string
	Path        string
	OperationID string
}

// Key returns the canonical METHOD /path key for this operation.
func (o Operation) Key() string {
	return RouteKey(o.Method, o.Path)
}

func buildAPI(root map[string]interface{}, source string) (*kitebuilder.API, []Operation, string, string, []string, error) {
	warnings := make([]string, 0)
	version := asString(root["openapi"])
	if version == "" {
		version = asString(root["swagger"])
	}

	title := ""
	if info, ok := asMap(root["info"]); ok {
		title = asString(info["title"])
	}

	basePath, serverURL := documentBasePath(root, version)

	api := &kitebuilder.API{
		ID:                  stableID(source, version, title, basePath),
		URL:                 serverURL,
		SecurityDefinitions: securityDefinitions(root, version),
		Paths:               make(map[kitebuilder.Path]kitebuilder.Operations),
	}
	if api.URL == "" {
		api.URL = title
	}
	if api.URL == "" {
		api.URL = source
	}

	paths, ok := asMap(root["paths"])
	if !ok {
		return nil, nil, "", "", warnings, fmt.Errorf("openapi document has no paths object")
	}

	globalConsumes := asStringSlice(root["consumes"])
	operations := make([]Operation, 0)

	for _, specPath := range sortedKeys(paths) {
		rawPathItem := paths[specPath]
		pathItem, err := resolveReference(root, rawPathItem, make(map[string]bool))
		if err != nil {
			warnings = append(warnings, fmt.Sprintf("%s: %v", specPath, err))
			pathItem = rawPathItem
		}
		pathMap, ok := asMap(pathItem)
		if !ok {
			warnings = append(warnings, fmt.Sprintf("%s: path item is not an object", specPath))
			continue
		}

		fullPath := joinPaths(basePath, specPath)
		pathParameters := parseParameterList(root, pathMap["parameters"], &warnings)
		if _, ok := api.Paths[kitebuilder.Path(fullPath)]; !ok {
			api.Paths[kitebuilder.Path(fullPath)] = make(kitebuilder.Operations)
		}

		for _, method := range httpMethods {
			rawOperation, ok := pathMap[method]
			if !ok {
				continue
			}

			rawOperation, err := resolveReference(root, rawOperation, make(map[string]bool))
			if err != nil {
				warnings = append(warnings, fmt.Sprintf("%s %s: %v", strings.ToUpper(method), fullPath, err))
				continue
			}
			operationMap, ok := asMap(rawOperation)
			if !ok {
				warnings = append(warnings, fmt.Sprintf("%s %s: operation is not an object", strings.ToUpper(method), fullPath))
				continue
			}

			parameters := mergeParameters(pathParameters, parseParameterList(root, operationMap["parameters"], &warnings))
			consumes := operationConsumes(root, operationMap, globalConsumes, version)

			if requestBody, contentType, ok := parseRequestBody(root, operationMap, &warnings); ok {
				parameters = append(parameters, requestBody)
				if len(contentType) > 0 {
					consumes = contentType
				}
			}

			operationID := asString(operationMap["operationId"])
			operations = append(operations, Operation{
				Method:      strings.ToUpper(method),
				Path:        fullPath,
				OperationID: operationID,
			})

			api.Paths[kitebuilder.Path(fullPath)][kitebuilder.OperationTypes(method)] = kitebuilder.Operation{
				Description: asString(operationMap["description"]),
				OperationID: operationID,
				Parameters:  parameters,
				Consumes:    toContentTypes(consumes),
				Produces:    toContentTypes(operationProduces(root, operationMap)),
			}
		}
	}

	sort.Slice(operations, func(i, j int) bool {
		return operations[i].Key() < operations[j].Key()
	})

	return api, operations, basePath, serverURL, warnings, nil
}

var httpMethods = []string{
	"get", "post", "put", "patch", "delete", "head", "options", "trace",
}

func parseParameterList(root interface{}, raw interface{}, warnings *[]string) []kitebuilder.Parameter {
	values, ok := asSlice(raw)
	if !ok {
		return nil
	}

	ret := make([]kitebuilder.Parameter, 0, len(values))
	for _, value := range values {
		resolved, err := resolveReference(root, value, make(map[string]bool))
		if err != nil {
			*warnings = append(*warnings, fmt.Sprintf("parameter: %v", err))
			continue
		}
		param, err := parameterFromValue(root, resolved)
		if err != nil {
			*warnings = append(*warnings, fmt.Sprintf("parameter: %v", err))
			continue
		}
		ret = append(ret, param)
	}
	return ret
}

func mergeParameters(base, operation []kitebuilder.Parameter) []kitebuilder.Parameter {
	if len(base) == 0 {
		return operation
	}
	if len(operation) == 0 {
		return base
	}

	overridden := make(map[string]bool, len(operation))
	for _, param := range operation {
		overridden[param.Name+"\x00"+strings.ToLower(param.In)] = true
	}

	ret := make([]kitebuilder.Parameter, 0, len(base)+len(operation))
	for _, param := range base {
		if overridden[param.Name+"\x00"+strings.ToLower(param.In)] {
			continue
		}
		ret = append(ret, param)
	}
	return append(ret, operation...)
}

func parameterFromValue(root interface{}, raw interface{}) (kitebuilder.Parameter, error) {
	m, ok := asMap(raw)
	if !ok {
		return kitebuilder.Parameter{}, fmt.Errorf("parameter is not an object")
	}

	ret := kitebuilder.Parameter{
		Description:     asString(m["description"]),
		In:              asString(m["in"]),
		Name:            asString(m["name"]),
		Required:        m["required"],
		Type:            asString(m["type"]),
		Format:          asString(m["format"]),
		Pattern:         asString(m["pattern"]),
		Example:         m["example"],
		Default:         m["default"],
		Minimum:         firstFloat(m["minimum"]),
		Maximum:         firstFloat(m["maximum"]),
		MaxLength:       asUint(m["maxLength"]),
		MaxItems:        asUint(m["maxItems"]),
		MinLength:       asUint(m["minLength"]),
		MinItems:        asUint(m["minItems"]),
		Enum:            asInterfaceSlice(m["enum"]),
		AllowEmptyValue: asBool(m["allowEmptyValue"]),
	}

	if schemaValue, ok := m["schema"]; ok && schemaValue != nil {
		ret.Schema = schemaFromValue(root, schemaValue, make(map[string]bool))
		// Leave Type empty so proute reads the schema's default/type instead of
		// treating the parameter itself as a primitive.
		ret.Type = ""
	} else if content, ok := asMap(m["content"]); ok {
		_, media, _ := firstMediaType(content)
		if media != nil {
			if schemaValue, ok := media["schema"]; ok {
				ret.Schema = schemaFromValue(root, schemaValue, make(map[string]bool))
				ret.Type = ""
			}
		}
	}

	if ret.Default == nil && ret.Example != nil {
		ret.Default = ret.Example
	}
	if ret.Default == nil && len(ret.Enum) > 0 {
		ret.Default = ret.Enum[0]
	}

	if items, ok := m["items"]; ok {
		ret.Items = schemaFromValue(root, items, make(map[string]bool))
	}

	return ret, nil
}

func parseRequestBody(root interface{}, operation map[string]interface{}, warnings *[]string) (kitebuilder.Parameter, []string, bool) {
	raw, ok := operation["requestBody"]
	if !ok {
		return kitebuilder.Parameter{}, nil, false
	}

	resolved, err := resolveReference(root, raw, make(map[string]bool))
	if err != nil {
		*warnings = append(*warnings, fmt.Sprintf("requestBody: %v", err))
		return kitebuilder.Parameter{}, nil, false
	}
	body, ok := asMap(resolved)
	if !ok {
		*warnings = append(*warnings, "requestBody is not an object")
		return kitebuilder.Parameter{}, nil, false
	}

	content, ok := asMap(body["content"])
	if !ok {
		return kitebuilder.Parameter{
			Name:     "body",
			In:       "body",
			Required: body["required"],
			Schema:   &kitebuilder.Schema{Type: "object"},
		}, nil, true
	}

	contentTypes := sortedKeys(content)
	_, media, _ := firstMediaType(content)
	if media == nil {
		media = make(map[string]interface{})
	}

	schema := &kitebuilder.Schema{Type: "object"}
	if schemaValue, ok := media["schema"]; ok {
		schema = schemaFromValue(root, schemaValue, make(map[string]bool))
	}

	return kitebuilder.Parameter{
		Name:        "body",
		In:          "body",
		Required:    body["required"],
		Description: asString(body["description"]),
		Schema:      schema,
	}, contentTypes, true
}

func firstMediaType(content map[string]interface{}) (string, map[string]interface{}, error) {
	if _, ok := content["application/json"]; ok {
		media, _ := asMap(content["application/json"])
		return "application/json", media, nil
	}
	for _, name := range sortedKeys(content) {
		media, ok := asMap(content[name])
		if !ok {
			continue
		}
		return name, media, nil
	}
	return "", nil, nil
}

func operationConsumes(root map[string]interface{}, operation map[string]interface{}, global []string, version string) []string {
	if version != "" && !strings.HasPrefix(version, "2") {
		if _, ok := operation["requestBody"]; ok {
			return nil
		}
		return nil
	}

	consumes := asStringSlice(operation["consumes"])
	if len(consumes) > 0 {
		return consumes
	}
	if len(global) > 0 {
		return global
	}
	return nil
}

func operationProduces(root map[string]interface{}, operation map[string]interface{}) []string {
	produces := asStringSlice(operation["produces"])
	if len(produces) > 0 {
		return produces
	}

package openapi

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"io/ioutil"
	"math"
	"os"
	"regexp"
	"sort"
	"strings"
)

// Coverage is a comparison between expected and actual route keys.
type Coverage struct {
	Expected int      `json:"expected"`
	Covered  int      `json:"covered"`
	Percent  float64  `json:"coverage_percent"`
	Missing  []string `json:"missing,omitempty"`
	Extra    []string `json:"extra,omitempty"`
}

// Complete reports whether all expected routes were generated.
func (c Coverage) Complete() bool {
	return len(c.Missing) == 0 && c.Expected == c.Covered
}

// CoverageReport summarises route generation for one spec.
type CoverageReport struct {
	Source    string    `json:"source"`
	Title     string    `json:"title,omitempty"`
	Version   string    `json:"version"`
	BasePath  string    `json:"base_path,omitempty"`
	ServerURL string    `json:"server_url,omitempty"`
	Spec      Coverage  `json:"spec"`
	Scannable Coverage  `json:"scannable"`
	Manual    *Coverage `json:"manual,omitempty"`
	Warnings  []string  `json:"warnings,omitempty"`

	// Convenience mirrors for dashboards that only read a top-level number.
	CoveragePercent       float64 `json:"coverage_percent"`
	ManualCoveragePercent float64 `json:"manual_coverage_percent,omitempty"`
}

var routeParamPattern = regexp.MustCompile(`\{[^{}]*\}`)

// RouteKey normalises a method and path to "METHOD /path".
func RouteKey(method, path string) string {
	method = strings.ToUpper(strings.TrimSpace(method))
	if method == "" {
		method = "GET"
	}
	path = strings.TrimSpace(path)
	if path == "" {
		path = "/"
	}
	if !strings.HasPrefix(path, "/") {
		path = "/" + path
	}
	return method + " " + path
}

// CanonicalRouteKey removes parameter names and query strings so two spellings
// of the same route compare as equal, e.g. /pet/{petId} and /pet/{id}.
func CanonicalRouteKey(key string) string {
	key = strings.TrimSpace(key)
	method := "GET"
	path := key
	if idx := strings.IndexAny(key, " \t"); idx >= 0 {
		method = strings.ToUpper(strings.TrimSpace(key[:idx]))
		path = strings.TrimSpace(key[idx+1:])
	}
	if len(path) >= 2 && path[0] == '/' && path[1] == '/' {
		// Leave protocol-relative values alone; they are not valid route keys
		// but we should not silently mangle them either.
	} else if idx := strings.Index(path, "://"); idx >= 0 {
		path = path[idx+3:]
		if slash := strings.Index(path, "/"); slash >= 0 {
			path = path[slash:]
		} else {
			path = "/"
		}
	}
	if idx := strings.Index(path, "?"); idx >= 0 {
		path = path[:idx]
	}
	if idx := strings.Index(path, "#"); idx >= 0 {
		path = path[:idx]
	}
	path = routeParamPattern.ReplaceAllString(path, "{}")
	path = strings.Replace(path, "//", "/", -1)
	if path == "" {
		path = "/"
	}
	if !strings.HasPrefix(path, "/") {
		path = "/" + path
	}
	if len(path) > 1 {
		path = strings.TrimRight(path, "/")
	}
	return method + " " + path
}

func compareCoverage(expected, actual []string) Coverage {
	expectedByCanonical := make(map[string]string, len(expected))
	for _, key := range expected {
		canonical := CanonicalRouteKey(key)
		if _, ok := expectedByCanonical[canonical]; !ok {
			expectedByCanonical[canonical] = RouteKeyFromKey(key)
		}
	}

	actualByCanonical := make(map[string]string, len(actual))
	for _, key := range actual {
		canonical := CanonicalRouteKey(key)
		if _, ok := actualByCanonical[canonical]; !ok {
			actualByCanonical[canonical] = RouteKeyFromKey(key)
		}
	}

	ret := Coverage{Expected: len(expectedByCanonical)}
	for canonical, original := range expectedByCanonical {
		if _, ok := actualByCanonical[canonical]; ok {
			ret.Covered++
		} else {
			ret.Missing = append(ret.Missing, original)
		}
	}
	for canonical, original := range actualByCanonical {
		if _, ok := expectedByCanonical[canonical]; !ok {
			ret.Extra = append(ret.Extra, original)
		}
	}

	sort.Strings(ret.Missing)
	sort.Strings(ret.Extra)
	if ret.Expected == 0 {
		ret.Percent = 100
	} else {
		ret.Percent = math.Round(float64(ret.Covered)*10000/float64(ret.Expected)) / 100
	}
	return ret
}

// RouteKeyFromKey normalises a single "METHOD /path" value while retaining its
// original path spelling.
func RouteKeyFromKey(key string) string {
	key = strings.TrimSpace(key)
	method := "GET"
	path := key
	if idx := strings.IndexAny(key, " \t"); idx >= 0 {
		method = strings.ToUpper(strings.TrimSpace(key[:idx]))
		path = strings.TrimSpace(key[idx+1:])
	}
	return RouteKey(method, path)
}

// LoadManualRoutes reads a manually curated list of routes from a file.
func LoadManualRoutes(filename string) ([]string, error) {
	f, err := os.Open(filename)
	if err != nil {
		return nil, fmt.Errorf("failed to open manual routes: %w", err)
	}
	defer f.Close()
	return ParseManualRoutes(f)
}

// ParseManualRoutes reads routes from lines such as "GET /pets/{id}" or
// "/pets/{id}". Blank lines and lines starting with # are ignored.
func ParseManualRoutes(r io.Reader) ([]string, error) {
	scanner := bufio.NewScanner(r)
	ret := make([]string, 0)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if idx := strings.Index(line, " #"); idx >= 0 {
			line = strings.TrimSpace(line[:idx])
		}

		fields := strings.Fields(line)
		if len(fields) == 0 {
			continue
		}
		if isHTTPMethod(fields[0]) {
			path := strings.Join(fields[1:], " ")
			ret = append(ret, RouteKey(fields[0], path))
			continue
		}
		ret = append(ret, RouteKey("GET", line))
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("failed to read manual routes: %w", err)
	}
	return sortUnique(ret), nil
}

func isHTTPMethod(value string) bool {
	switch strings.ToUpper(value) {
	case "GET", "POST", "PUT", "PATCH", "DELETE", "HEAD", "OPTIONS", "TRACE":
		return true
	default:
		return false
	}
}

// WriteText writes a human-readable coverage report.
func (r CoverageReport) WriteText(w io.Writer) error {
	title := r.Title
	if title == "" {
		title = r.Source
	}
	if _, err := fmt.Fprintf(w, "Spec: %s\n", title); err != nil {
		return err
	}
	if _, err := fmt.Fprintf(w, "Source: %s\n", r.Source); err != nil {
		return err
	}
	if _, err := fmt.Fprintf(w, "Version: %s\n", r.Version); err != nil {
		return err
	}
	if r.BasePath != "" {
		if _, err := fmt.Fprintf(w, "Base path: %s\n", r.BasePath); err != nil {
			return err
		}
	}
	if _, err := fmt.Fprintf(w, "Spec routes: %d\n", r.Spec.Expected); err != nil {
		return err
	}
	if _, err := fmt.Fprintf(w, "Generated routes: %d\n", r.Spec.Covered+len(r.Spec.Extra)); err != nil {
		return err
	}
	if _, err := fmt.Fprintf(w, "Route coverage: %.2f%% (%d/%d)\n", r.Spec.Percent, r.Spec.Covered, r.Spec.Expected); err != nil {
		return err
	}
	if _, err := fmt.Fprintf(w, "Scannable coverage: %.2f%% (%d/%d)\n", r.Scannable.Percent, r.Scannable.Covered, r.Scannable.Expected); err != nil {
		return err
	}
	if r.Manual != nil {
		if _, err := fmt.Fprintf(w, "Manual baseline: %.2f%% (%d/%d)\n", r.Manual.Percent, r.Manual.Covered, r.Manual.Expected); err != nil {
			return err
		}
	}
	if err := writeRouteList(w, "Missing routes", r.Spec.Missing); err != nil {
		return err
	}
	if err := writeRouteList(w, "Unexpected routes", r.Spec.Extra); err != nil {
		return err
	}
	if r.Manual != nil {
		if err := writeRouteList(w, "Missing from manual baseline", r.Manual.Missing); err != nil {
			return err
		}
		if err := writeRouteList(w, "Unexpected vs manual baseline", r.Manual.Extra); err != nil {
			return err
		}
	}
	return writeRouteList(w, "Warnings", r.Warnings)
}

func writeRouteList(w io.Writer, heading string, values []string) error {
	if len(values) == 0 {
		return nil
	}
	if _, err := fmt.Fprintf(w, "%s:\n", heading); err != nil {
		return err
	}
	for _, value := range values {
		if _, err := fmt.Fprintf(w, "  - %s\n", value); err != nil {
			return err
		}
	}
	return nil
}

// WriteJSON writes an indented JSON coverage report.
func (r CoverageReport) WriteJSON(w io.Writer) error {
	data, err := json.MarshalIndent(r, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	_, err = w.Write(data)
	return err
}

// Write writes the coverage report in text or JSON format.
func (r CoverageReport) Write(w io.Writer, format string) error {
	switch strings.ToLower(format) {
	case "", "text", "pretty":
		return r.WriteText(w)
	case "json":
		return r.WriteJSON(w)
	default:
		return fmt.Errorf("unsupported report format: %s", format)
	}
}

// WriteReports writes one or more reports. JSON output is always an array.
func WriteReports(w io.Writer, reports []CoverageReport, format string) error {
	if !strings.EqualFold(format, "json") {
		for i, report := range reports {
			if i > 0 {
				if _, err := fmt.Fprintln(w); err != nil {
					return err
				}
			}
			if err := report.WriteText(w); err != nil {
				return err
			}
		}
		return nil
	}

	data, err := json.MarshalIndent(reports, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	_, err = w.Write(data)
	return err
}

// WriteReportFile writes reports to a file.
func WriteReportFile(filename string, reports []CoverageReport, format string) error {
	var w io.Writer = os.Stdout
	if filename != "" {
		f, err := os.Create(filename)
		if err != nil {
			return fmt.Errorf("failed to create report file: %w", err)
		}
		defer f.Close()
		w = f
	}
	return WriteReports(w, reports, format)
}

package openapi

import (
	"github.com/assetnote/kiterunner/pkg/kitebuilder"
)

// schemaFromValue converts a Swagger/OpenAPI schema into the kitebuilder
// schema used by proute. Reference cycles are cut off with an empty object
// schema so recursive models cannot make the route generator recurse forever.
func schemaFromValue(root interface{}, raw interface{}, stack map[string]bool) *kitebuilder.Schema {
	m, ok := asMap(raw)
	if !ok || len(m) == 0 {
		return &kitebuilder.Schema{Type: "object"}
	}

	if ref, ok := m["$ref"].(string); ok && ref != "" {
		if stack[ref] {
			return &kitebuilder.Schema{Type: "object"}
		}

		target, err := lookupJSONPointer(root, ref)
		if err != nil {
			return &kitebuilder.Schema{Type: "object"}
		}

		stack[ref] = true
		ret := schemaFromValue(root, target, stack)
		delete(stack, ref)

		if len(m) > 1 {
			ret = mergeSchemas(ret, schemaFromValue(root, withoutRef(m), stack))
		}
		return ret
	}

	ret := &kitebuilder.Schema{}
	ret.Type = schemaType(m)
	ret.Title = asString(m["title"])
	ret.Format = asString(m["format"])
	ret.Description = asString(m["description"])
	ret.Pattern = asString(m["pattern"])
	ret.Name = asString(m["name"])
	ret.CollectionFormat = asString(m["collectionFormat"])
	ret.Nullable = asBool(m["nullable"])
	ret.ReadOnly = asBool(m["readOnly"])
	ret.WriteOnly = asBool(m["writeOnly"])
	ret.AllowEmptyValue = asBool(m["allowEmptyValue"])
	ret.Enum = asInterfaceSlice(m["enum"])
	ret.Min = firstFloat(m["minimum"], m["min"])
	ret.Max = firstFloat(m["maximum"], m["max"])
	ret.MultipleOf = firstFloat(m["multipleOf"])
	ret.MinLength = asUint(m["minLength"])
	ret.MaxLength = asUint(m["maxLength"])
	ret.MinItems = asUint(m["minItems"])
	ret.MaxItems = asUint(m["maxItems"])
	ret.MinProps = asUint(m["minProperties"])
	ret.MaxProps = asUint(m["maxProperties"])
	ret.ExclusiveMin = asBool(m["exclusiveMinimum"])
	ret.ExclusiveMax = asBool(m["exclusiveMaximum"])
	ret.UniqueItems = asBool(m["uniqueItems"])

	if required, ok := m["required"]; ok {
		switch required.(type) {
		case bool:
			ret.Required = required
		default:
			if names := asStringSlice(required); len(names) > 0 {
				ret.Required = names
			}
		}
	}

	if properties, ok := asMap(m["properties"]); ok {
		ret.Properties = make(map[string]kitebuilder.Schema, len(properties))
		for name, value := range properties {
			ret.Properties[name] = *schemaFromValue(root, value, stack)
		}
	}

	if items, ok := m["items"]; ok {
		ret.Items = schemaFromValue(root, items, stack)
	}

	if additional, ok := m["additionalProperties"]; ok {
		if additionalMap, isMap := asMap(additional); isMap {
			ret.AdditionalProperties = schemaFromValue(root, additionalMap, stack)
		} else if asBool(additional) {
			ret.AdditionalProperties = &kitebuilder.Schema{Type: "object"}
		}
	}

	if allOf, ok := asSlice(m["allOf"]); ok {
		for _, item := range allOf {
			ret = mergeSchemas(ret, schemaFromValue(root, item, stack))
		}
	}

	// For route/body generation a deterministic representative schema is more
	// useful than preserving every union branch.
	for _, key := range []string{"oneOf", "anyOf"} {
		if options, ok := asSlice(m[key]); ok && len(options) > 0 {
			ret = mergeSchemas(ret, schemaFromValue(root, options[0], stack))
			break
		}
	}

	value := m["default"]
	if value == nil {
		value = m["example"]
	}
	if value == nil && len(ret.Enum) > 0 {
		value = ret.Enum[0]
	}
	if value != nil {
		ret.Default = value
	}
	if example, ok := m["example"]; ok {
		ret.Example = example
	}

	return ret
}

func schemaType(m map[string]interface{}) string {
	if t := asString(m["type"]); t != "" {
		return t
	}
	if types, ok := asSlice(m["type"]); ok {
		for _, item := range types {
			if t := asString(item); t != "" && t != "null" {
				return t
			}
		}
	}
	if _, ok := m["properties"]; ok {
		return "object"
	}
	if _, ok := m["additionalProperties"]; ok {
		return "object"
	}
	if _, ok := m["items"]; ok {
		return "array"
	}
	if _, ok := m["allOf"]; ok {
		return "object"
	}
	return ""
}

func mergeSchemas(base, overlay *kitebuilder.Schema) *kitebuilder.Schema {
	if base == nil {
		return overlay
	}
	if overlay == nil {
		return base
	}

	ret := *base
	if overlay.Type != "" {
		ret.Type = overlay.Type
	}
	if overlay.Title != "" {
		ret.Title = overlay.Title
	}
	if overlay.Format != "" {
		ret.Format = overlay.Format
	}
	if overlay.Description != "" {
		ret.Description = overlay.Description
	}
	if overlay.Pattern != "" {
		ret.Pattern = overlay.Pattern
	}
	if overlay.Name != "" {
		ret.Name = overlay.Name
	}
	if overlay.CollectionFormat != "" {
		ret.CollectionFormat = overlay.CollectionFormat
	}
	if overlay.Default != nil {
		ret.Default = overlay.Default
	}
	if overlay.Example != nil {
		ret.Example = overlay.Example
	}
	if len(overlay.Enum) > 0 {
		ret.Enum = overlay.Enum
	}
	if overlay.Required != nil {
		ret.Required = overlay.Required
	}
	if overlay.Items != nil {
		ret.Items = overlay.Items
	}
	if overlay.AdditionalProperties != nil {
		ret.AdditionalProperties = overlay.AdditionalProperties
	}
	if len(overlay.Properties) > 0 {
		if ret.Properties == nil {
			ret.Properties = make(map[string]kitebuilder.Schema, len(overlay.Properties))
		}
		for k, v := range overlay.Properties {
			ret.Properties[k] = v
		}
	}
	ret.AllOf = append(ret.AllOf, overlay.AllOf...)
	return &ret
}

func asInterfaceSlice(v interface{}) []interface{} {
	if values, ok := asSlice(v); ok {
		return values
	}
	return nil
}

func firstFloat(values ...interface{}) float64 {
	for _, value := range values {
		if f, ok := asFloat(value); ok {
			return f
		}
	}
	return 0
}

