func LoadOpenAPIFile(fns []string) ScanOption {
	return func(o *ScanOptions) error {
		for _, filename := range fns {
			if filename == "" {
				continue
			}
			doc, err := openapi.LoadFile(filename)
			if err != nil {
				return fmt.Errorf("failed to load OpenAPI spec %s: %w", filename, err)
